-- Track deadlines generated from placement dates so later rescheduling can
-- update only automation-owned deadlines and never overwrite staff overrides.
ALTER TABLE public.deployment_tasks
  ADD COLUMN IF NOT EXISTS auto_due_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS auto_due_rule TEXT;

COMMENT ON COLUMN public.deployment_tasks.auto_due_at IS
  'Last due_at value generated by a system scheduling rule; null when staff owns the due date.';
COMMENT ON COLUMN public.deployment_tasks.auto_due_rule IS
  'Rule key that generated auto_due_at, for example arrival_minus_10_days.';
